    "question": "Dans la carence en facteurs antipernicieux :",
    "propositions": {
      "A": "Les réserves en vit B9 sont importantes couvrent largement les besoins.",
      "B": "Le dosage vitaminique confirme le diagnostic.",
      "C": "L'hémogramme d'une anémie de Biermer non traitée peut associer une anémie à une thrombopénie.",
      "D": "La supplémentation en acide folique est systématique en cas de grossesse.",
      "E": "En cas de gastrectomie la vit B12 est maintenue à vie."
    },
    "bonnes_reponses": [
      "B",
      "C",
      "D",
      "E"
    ],
    "explication": "Les réserves hépatiques en vitamine B9 (folates) sont faibles (couvrent seulement 3 à 4 mois de besoins, A faux), contrairement à la vitamine B12 (3 à 5 ans de réserves). Le dosage sérique de vitamine B12 et des folates sériques/érythrocytaires confirme la carence (B). La dysérythropoïèse mégaloblastique sévère touche les 3 lignées (avortement intramédullaire), créant une pancytopénie avec anémie macrocytaire et thrombopénie (C). La supplémentation périconceptionnelle en acide folique est obligatoire pour prévenir les anomalies de fermeture du tube neural (spina bifida) (D). La gastrectomie totale supprime la sécrétion du facteur intrinsèque et impose une supplémentation parentérale à vie en vitamine B12 (E).",
    "justifications": {
      "A": "Faux. Les réserves en folates (B9) sont très faibles (3-4 mois) ; les réserves en vitamine B12 sont importantes (plusieurs années).",
      "B": "Vrai (Corrigé officiel : B). Le dosage de la vitamine B12 sérique (< 150 pmol/L) et folates (< 5 µg/L) apporte la certitude biologique.",
      "C": "Vrai (Corrigé officiel : C). L'atteinte mégaloblastique globale donne une anémie macrocytaire souvent accompagnée de thrombopénie et leucopénie.",
      "D": "Vrai (Corrigé officiel : D). Supplémentation systématique (0.4 mg/j dès la période préconceptionnelle) pour prévenir les anomalies du tube neural.",
      "E": "Vrai (Corrigé officiel : E). Absence de cellules pariétales gastriques = absence de facteur intrinsèque = traitement parentéral à vie.",
      "_synthese": "Carences B12 / B9 : Réserves B9 faibles, B12 fortes. Pancytopénie fréquente (C). Folates systématiques lors de la grossesse (D), B12 à vie post-gastrectomie (E).",
      "_remarque": "Piège classique : Ne jamais donner d'acide folique seul sans vitamine B12 en cas d'anémie de Biermer (aggravation de la sclérose combinée de la moelle)."
    }
