    "question": "Les anémies hémolytiques corpusculaires :",
    "propositions": {
      "A": "Peuvent être responsable de triade hémolytique",
      "B": "Dans la Bthalassemie l'hémochromatose peut être responsable de complications viscérales.",
      "C": "Dans la drépanocytose un programme d'échange transfusionnel peut être proposé pour réduire le taux d'hémoglobine S.",
      "D": "Dans la microspherocytose héréditaire Le test de résistance globulaire aux solutions hypotoniques pose le diagnostic.",
      "E": "La supplémentation en acide folique est systématique."
    },
    "bonnes_reponses": [
      "A",
      "B",
      "C",
      "D",
      "E"
    ],
    "explication": "Toutes les propositions sont exactes (grille officielle : ABCDE). Les anémies hémolytiques corpusculaires constitutionnelles partagent la triade hémolytique : pâleur, ictère à bilirubine libre et splénomégalie (A). La bêta-thalassémie majeure avec transfusions itératives induit une hémochromatose post-transfusionnelle (atteinte cardiaque, hépatique, endocrine) (B). Dans la drépanocytose, l'échange transfusionnel (érythraphérèse) diminue l'HbS < 30 % pour prévenir les AVC et le syndrome thoracique aigu (C). Dans la maladie de Minkowski-Chauffard, le test de résistance osmotique aux solutions hypotoniques montre une fragilité accrue des sphérocytes (D). L'hyperactivité régénérative médullaire consomme les folates et impose une supplémentation systématique en vitamine B9 (E).",
    "justifications": {
      "A": "Vrai (Corrigé officiel : A). Triade clinique d'hémolyse chronique : pâleur, subictère conjonctival et splénomégalie.",
      "B": "Vrai (Corrigé officiel : B). La surcharge en fer viscérale (insuffisance cardiaque, cirrhose) est la première cause de mortalité sans chélateur.",
      "C": "Vrai (Corrigé officiel : C). L'échange transfusionnel manuel ou automatisé réduit l'HbS et prévient les crises vaso-occlusives graves.",
      "D": "Vrai (Corrigé officiel : D). L'hémolyse précoce en milieu hypotonique signe la sphérocytose héréditaire.",
      "E": "Vrai (Corrigé officiel : E). L'érythropoïèse intense compense l'hémolyse et épuise rapidement les réserves en acide folique.",
      "_synthese": "Anémies hémolytiques corpusculaires : Triade (A), Hémochromatose (B), Échanges transfusionnels dans la drépanocytose (C), Fragilité osmotique (D), Acide folique obligatoire (E).",
      "_remarque": "Clé officielle de la Faculté de Mostaganem : A, B, C, D, E (toutes vraies)."
    }
