    "question": "Les anémies hémolytiques extra corpusculaires acquises :",
    "propositions": {
      "A": "Peuvent être immunologiques ou non immunologiques.",
      "B": "Dans l'AHAI le test de Coombs direct détecte les anticorps fixés sur la paroi du globule rouge",
      "C": "Au cours du syndrome hémolytique et urémique du NRS (SHU) le FSP retrouve des schizocytes",
      "D": "Dans les AHAI la transfusion est indiquée si anémie < 8gr/dl",
      "E": "Dans les anémies hémolytiques d'origine mécanique le traitement de 1ere intension repose sur la corticothérapie"
    },
    "bonnes_reponses": [
      "A",
      "B",
      "C"
    ],
    "explication": "Les anémies hémolytiques extracorpusculaires acquises comprennent les causes immunologiques (AHAI, allo-immunisation) et non immunologiques (mécaniques, infectieuses, toxiques) (A). Le test de Coombs direct (TDA) met en évidence les IgG ou le complément fixés in vivo sur la membrane érythrocytaire (B). Le SHU est une microangiopathie thrombotique (MAT) caractérisée par la présence de schizocytes (hématies fragmentées > 1-2 %) sur frottis de sang périphérique (C). Dans l'AHAI, la transfusion est dangereuse (risque d'hémolyse aiguë) et réservée à l'anémie mal tolérée menaçant le pronostic vital (D faux). Dans l'hémolyse mécanique, le traitement est étiologique chirurgical (remplacement de valve) et non par corticoïdes (E faux).",
    "justifications": {
      "A": "Vrai (Corrigé officiel : A). Classification nosologique standard des anémies extracorpusculaires acquises.",
      "B": "Vrai (Corrigé officiel : B). Le test direct à l'antiglobuline affirme la nature auto-immune de l'hémolyse.",
      "C": "Vrai (Corrigé officiel : C). Les schizocytes attestent du cisaillement mécanique des hématies sur les thrombi de fibrine microvasculaires.",
      "D": "Faux. Dans l'AHAI, la transfusion est à haut risque d'allo-immunisation et d'accident hémolytique ; elle n'est guidée que par la tolérance clinique.",
      "E": "Faux. Les corticoïdes sont le traitement des AHAI à anticorps chauds, mais inefficaces dans l'hémolyse mécanique qui nécessite la correction de l'obstacle.",
      "_synthese": "Anémies extracorpusculaires acquises : Causes immuno et non immuno (A), Test de Coombs direct (B), Schizocytes dans le SHU (C). Transfusion prudente.",
      "_remarque": "Schizocytes > 1% = signature hématologique d'une microangiopathie thrombotique (SHU / PTT)."
    }
