    "question": "Concernant le système Rhésus, quelles sont les propositions vraies ?",
    "propositions": {
      "A": "Il existe 6 types d'antigènes dans ce groupe : D/d/C/c/E/e",
      "B": "Un patient Rhésus D négatif (RH-1) possède un gène « d »",
      "C": "Les antigènes Rhésus sont strictement érythrocytaires",
      "D": "L'absence de protéine « C » impose obligatoirement la présence de la protéine « c »",
      "E": "Les anticorps du système Rhésus sont naturels et réguliers existant en dehors de toute stimulation"
    },
    "bonnes_reponses": [
      "C",
      "D"
    ],
    "explication": "Dans le système Rhésus : les antigènes Rhésus sont des protéines transmembranaires strictement érythrocytaires (absentes des leucocytes, plaquettes et tissus solubles, C vrai). Il n'existe que 5 antigènes majeurs définis sérologiquement : D, C, c, E, e (l'antigène 'd' n'existe pas, la lettre 'd' désignant seulement l'absence phénotypique de D ; il n'y a pas de gène 'd', A et B faux). Le locus RHCE code pour les allèles codominants C/c et E/e : un individu ne possédant pas l'antigène C exprime obligatoirement l'antigène c (homozygote c/c) (D vrai). Les anticorps du système Rhésus (anti-D, anti-C, anti-E...) sont des anticorps immuns acquis irréguliers résultant d'une allo-immunisation après transfusion ou grossesse (E faux : seuls les anticorps ABO sont naturels et réguliers).",
    "justifications": {
      "A": "Faux. Il existe 5 antigènes sérologiques principaux (D, C, c, E, e). L'antigène 'd' n'existe pas physiquement.",
      "B": "Faux. Il n'y a pas de gène 'd' ; le statut RH négatif est lié à la délétion complète du gène RHD.",
      "C": "Vrai (Corrigé officiel : C). Les protéines Rhésus sont spécifiques de la membrane du globule rouge.",
      "D": "Vrai (Corrigé officiel : D). Le polymorphisme codominant du gène RHCE impose la présence de l'allèle c chez les sujets non porteurs de l'allèle C.",
      "E": "Faux. Les anticorps anti-Rhésus sont toujours immuns irréguliers (acquis par allo-immunisation).",
      "_synthese": "Système Rhésus : 5 antigènes (D, C, c, E, e), strictement érythrocytaires (C), absence de C implique présence de c (D). Anticorps toujours immuns acquis.",
      "_remarque": "L'antigène D (RH1) est le plus immunogène de tous les antigènes sanguins après les antigènes A et B."
    }
