    "question": "Concernant la vit B9 :",
    "propositions": {
      "A": "Les réserves sont importantes couvrent largement les besoins.",
      "B": "Le dosage vitaminique confirme le diagnostic.",
      "C": "En cas de carence, l'hémogramme peut révéler une pancytopénie",
      "D": "La supplémentation en acide folique est systématique en cas de grossesse.",
      "E": "En cas de gastrectomie la vit B9 est maintenue à vie."
    },
    "bonnes_reponses": [
      "B",
      "C",
      "D"
    ],
    "explication": "Les folates (vitamine B9) sont présents dans les légumes verts ; leurs réserves hépatiques sont faibles (3 à 4 mois) (A faux). Le dosage des folates sériques (< 5 nmol/L) et érythrocytaires (< 300 nmol/L) confirme le diagnostic (B vrai). L'avortement intramédullaire mégaloblastique des précurseurs touchant les trois lignées hématopoïétiques peut provoquer une pancytopénie arégénérative (C vrai). La supplémentation systématique en acide folique (0,4 mg/j) est obligatoire en périconceptionnel pour prévenir les anomalies du tube neural (spina bifida) (D vrai). L'absorption des folates s'effectue au niveau du jéjunum proximal et ne nécessite pas de facteur intrinsèque gastrique ; la gastrectomie n'impose donc pas de supplémentation à vie en B9 (contrairement à la B12, E faux).",
    "justifications": {
      "A": "Faux. Les réserves en folates sont modestes et s'épuisent rapidement en quelques mois en cas d'arrêt d'apport.",
      "B": "Vrai (Corrigé officiel : B). Le dosage des folates intra-érythrocytaires reflète le statut tissulaire des derniers mois.",
      "C": "Vrai (Corrigé officiel : C). Pancytopénie par dysérythropoïèse, thrombopoïèse et granulopoïèse inefficaces.",
      "D": "Vrai (Corrigé officiel : D). Mesure de santé publique systématique préconceptionnelle et du 1er trimestre.",
      "E": "Faux. C'est la vitamine B12 qui doit être maintenue à vie après gastrectomie, pas la B9.",
      "_synthese": "Vitamine B9 : Réserves faibles, dosage confirmateur (B), risque de pancytopénie (C) et supplémentation systématique de la femme enceinte (D).",
      "_remarque": "Principale cause de carence en folates : malnutrition, alcoolisme, malabsorption cœliaque et médicaments antifoliques (méthotrexate)."
    }
