    "question": "Concernant la LMC :",
    "propositions": {
      "A": "C'est une hémopathie maligne",
      "B": "C'est un syndrome lymphoproliferatif chronique",
      "C": "Elle Fait partie des syndromes myéloprolifératifs chroniques",
      "D": "Peut évoluer en trois phase : chronique, accélérée, transformation",
      "E": "Peut se transformer en myélofibrose ou leucémie aigue"
    },
    "bonnes_reponses": [
      "A",
      "C",
      "D",
      "E"
    ],
    "explication": "La LMC est une hémopathie maligne clonale de la cellule souche hématopoïétique (A). Elle appartient au groupe des néoplasies myéloprolifératives chroniques (NMP BCR-ABL1 positif) et non aux syndromes lymphoprolifératifs (B faux, C vrai). Son histoire naturelle non traitée évolue classiquement en 3 phases successives : phase chronique initiale, phase accélérée intermédiaire, et phase de transformation / crise blastique terminale (D vrai). Elle peut évoluer vers une myélofibrose secondaire ou se transformer en leucémie aiguë (myéloïde dans 70 % des cas, lymphoblastique dans 30 % des cas) (E vrai).",
    "justifications": {
      "A": "Vrai (Corrigé officiel : A). Néoplasie clonale acquise de la cellule souche pluripotente.",
      "B": "Faux. C'est un syndrome myéloprolifératif et non lymphoprolifératif.",
      "C": "Vrai (Corrigé officiel : C). Chef de file des syndromes myéloprolifératifs chroniques avec la maladie de Vaquez, la thrombocytémie essentielle et la splénomégalie myéloïde.",
      "D": "Vrai (Corrigé officiel : D). Évolution triphasique classique de la maladie.",
      "E": "Vrai (Corrigé officiel : E). Transformation terminale en leucémie aiguë ou myélofibrose avec pancytopénie.",
      "_synthese": "LMC : Hémopathie maligne myéloproliférative (A, C), évolution triphasique (D), risque de transformation en leucémie aiguë ou myélofibrose (E).",
      "_remarque": "L'avènement des inhibiteurs de tyrosine kinase (imatinib) a transformé le pronostic, bloquant l'évolution vers l'acutisation."
    }
