      "B": "Faux. L'AHAI détruit sélectivement les hématies en périphérie par auto-anticorps, laissant les leucocytes et les plaquettes normaux.",
      "C": "Vrai (Corrigé officiel : ACDE). Le blocage de la synthèse d'ADN donne une érythropoïèse inefficace sévère avec apoptose intramédullaire des précurseurs des 3 lignées.",
      "D": "Vrai (Corrigé officiel : ACDE). L'envahissement néoplasique médullaire (myélophtisie avec myélémie/érythroblastose) aboutit à une pancytopénie.",
